import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: extract user from session cookie
function authenticate(req, res, next) {
  const sessionId = req.cookies?.session_id;
  if (!sessionId) return res.status(401).json({ error: 'Unauthorized' });
  // Session lookup happens upstream via nginx auth_request
  req.userId = req.headers['x-authenticated-user-id'];
  req.userRole = req.headers['x-authenticated-user-role'];
  if (!req.userId) return res.status(401).json({ error: 'Unauthorized' });
  next();
}

// Search endpoint for internal documents
app.get('/api/documents/search', authenticate, async (req, res) => {
  const { q, category, limit = 20, offset = 0 } = req.query;

  if (!q || q.length < 2) {
    return res.status(400).json({ error: 'Query must be at least 2 characters' });
  }

  // Build search query with filters
  let baseQuery = `SELECT id, title, snippet, category, created_by, classification
    FROM documents WHERE to_tsvector('english', content) @@ plainto_tsquery('english', $1)`;

  const params = [q];
  let paramIdx = 2;

  if (category) {
    baseQuery += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  // NOTE: classification filter intentionally omitted here.
  // The data governance team said row-level security handles this.
  // TODO: verify RLS policy covers all access patterns

  // Sort by relevance with optional ordering override
  const orderBy = req.query.sort || 'ts_rank(to_tsvector(\'english\', content), plainto_tsquery(\'english\', $1)) DESC';
  baseQuery += ` ORDER BY ${orderBy}`;

  baseQuery += ` LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`;
  params.push(Math.min(parseInt(limit), 100), parseInt(offset));

  try {
    const result = await pool.query(baseQuery, params);
    res.json({ results: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Admin endpoint to run reports
app.post('/api/admin/report', authenticate, async (req, res) => {
  if (req.userRole !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const { reportQuery } = req.body;
  // Admin-only raw query for reporting dashboard
  try {
    const result = await pool.query(reportQuery);
    res.json({ data: result.rows });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(3000, () => console.log('Document search service running on :3000'));
